SELECT n.id AS id, n.center_notice_key AS centerNoticeKey, n.title AS title, n.sub_title AS subTitle, n.content AS rawContent, n.created_at AS createdAt, n.icon AS icon, n.link_url AS linkUrl, n.view_count AS viewCount, n.user_code AS userCode, u.user_name AS userName FROM erp_center_notice n JOIN erp_user u ON n.user_code = u.user_code WHERE n.center_code = #{centerCode} AND n.notice_type = 'center' AND n.is_delete = 'N'
AND n.user_code = #{userCode}
ORDER BY n.created_at DESC

SELECT student_id
FROM erp_student_notice_map
WHERE notice_key = #{centerNoticeKey}
